/* @lc app=leetcode id=1728 lang=kotlin */ class Solution { fun reach(g: Array<String>, p: Int, j: Int): List<Int> = g[0].length.let { c -> listOf(p) + listOf(0 to 1, 0 to -1, 1 to 0, -1 to 0).flatMap { (dr, dc) -> (1..j).map { p / c + it * dr to p % c + it * dc }.takeWhile { (r, cc) -> r in g.indices && cc in 0 until c && g[r][cc] != '#' }.map { (r, cc) -> r * c + cc } } } fun sq(res: IntArray, q: java.util.ArrayDeque<Int>, p: Int, r: Int) = r.also { res[p] = it }.also { q.add(p) } fun canMouseWin(grid: Array<String>, catJump: Int, mouseJump: Int): Boolean = grid[0].length.let { C -> (grid.size * C).let { N -> grid.joinToString("").let { f -> f.indexOf('F').let { food -> f.indexOf('M').let { m0 -> f.indexOf('C').let { c0 -> IntArray(N * N * 2).let { res -> java.util.ArrayDeque<Int>().let { q -> IntArray(N * N * 2) { s -> (s / 2).let { mc -> if (f[mc / N] == '#' || f[mc % N] == '#') 0 else if (s % 2 == 0) reach(grid, mc / N, mouseJump).size else reach(grid, mc % N, catJump).size } }.let { deg -> (0 until N).filter { f[it] != '#' }.forEach { m -> (0 until N).filter { f[it] != '#' }.forEach { c -> (0..1).forEach { t -> if (m == c || c == food) sq(res, q, (m * N + c) * 2 + t, 2) else if (m == food) sq(res, q, (m * N + c) * 2 + t, 1) } } }.let { generateSequence { q.poll() }.forEach { s -> (s / 2).let { mc -> (mc / N).let { m -> (mc % N).let { c -> res[s].let { r -> (if (s % 2 == 1) reach(grid, m, mouseJump).map { (it * N + c) * 2 } else reach(grid, c, catJump).map { (m * N + it) * 2 + 1 }).filter { res[it] == 0 }.forEach { p -> if (p % 2 == 0 && r == 1 || p % 2 == 1 && r == 2 || --deg[p] == 0) sq(res, q, p, r) } } } } } }.let { res[(m0 * N + c0) * 2] == 1 } } } } } } } } } } } }